    uniform vec2 lightCenterPoint;
    uniform highp float lightAngle;
    uniform highp float lightWidth;
    uniform highp float enableGradient;
    uniform highp float cropAlpha;
    uniform highp float enableFog;
  vec4 addLightColor(vec4 textureColor, vec4 lightColor, vec2 lightCenterPoint, float lightAngle, float lightWidth) {
    if (lightWidth <= 0.0) {
      return textureColor;
    }
    float angleInRadians = radians(lightAngle);
    float dis = 0.0;
    float angleMod = mod(lightAngle, 180.0);
    if (abs(angleMod) > 0.001) {
      float tanValue = tan(angleInRadians);
      if (abs(tanValue) > 1000.0) {
        dis = abs(uv0.x - lightCenterPoint.x);
      } else {
        float lightOffsetX = lightCenterPoint.x - ((1.0 - lightCenterPoint.y) / tanValue);
        float dx = lightOffsetX + (1.0 - uv0.y) / tanValue;
        float offsetDis = abs(uv0.x - dx);
        dis = sin(angleInRadians) * offsetDis;
      }
    } else {
      dis = abs(uv0.y - lightCenterPoint.y);
    }
    float a = 1.0 ;
    if (cropAlpha > 0.5) {
      a *= step(0.01, textureColor.a);
    }
    if (enableFog <= 0.5) {
      a *= step(dis, lightWidth * 0.5);
    }
    if (enableGradient > 0.5) {
      float halfWidth = lightWidth * 0.5;
      if (halfWidth > 0.001) {
        a *= 1.0 - dis / halfWidth;
      } else {
        a *= 0.0;
      }
    }
    vec4 finalLightColor = lightColor * a;
      #if ENABLE_ORIGINCOLOR
        finalLightColor = textureColor + textureColor * a;
      #else
        finalLightColor = textureColor + finalLightColor;
        finalLightColor.a = textureColor.a;
      #endif
      return finalLightColor;
    }
#endif
vec4 frag () {
  vec4 o = vec4(1, 1, 1, 1);
  #if USE_TEXTURE
    o *= CCSampleWithAlphaSeparated(cc_spriteTexture, uv0);
  #endif
  o *= color;
  ALPHA_TEST(o);
  #if ENABLE_LIGHT
    o = addLightColor(o, lightColor, lightCenterPoint, lightAngle, lightWidth);
  #endif
  return o;
}
void main() { gl_FragColor = frag(); }

